import type { TokenDictionary } from '../types.js';

/**
 * Generates the StyleX `vars.stylex.ts` source code containing `stylex.defineVars(...)`.
 */
export function generateStylexVars(dict: TokenDictionary): string {
  const lines: string[] = [
    '/**',
    ' * @file Automatically generated by @pine-ui/token-compiler.',
    ' * DO NOT EDIT MANUALLY.',
    ' */',
    "import * as stylex from '@stylexjs/stylex';",
    '',
    '/** Typed StyleX design token contracts */',
    'export const vars = stylex.defineVars({',
  ];

  // Combine semantic light tokens with layout & primitive scale variables
  const allVars = new Map<string, { cssVar: string; fallback: string | number }>();

  // Semantics first (components consume semantic tokens)
  for (const token of dict.semantics.light.values()) {
    allVars.set(token.stylexKey, {
      cssVar: token.cssVariable,
      fallback: token.resolvedValue,
    });
  }

  // Primitive layout, spacing, radii, typography scales
  for (const token of dict.primitives.values()) {
    if (!allVars.has(token.stylexKey)) {
      allVars.set(token.stylexKey, {
        cssVar: token.cssVariable,
        fallback: token.resolvedValue,
      });
    }
  }

  // Sort keys for deterministic output
  const sortedKeys = Array.from(allVars.keys()).sort();

  for (const key of sortedKeys) {
    const { cssVar, fallback } = allVars.get(key)!;
    const valueString = JSON.stringify(`var(${cssVar}, ${fallback})`);
    lines.push(`  ${key}: ${valueString},`);
  }

  lines.push('});', '');
  lines.push('export const tokens = vars;', '');

  return lines.join('\n');
}

/**
 * Generates `tokens.ts` export barrel for `@pine-ui/stylex`.
 */
export function generateStylexTokensBarrel(): string {
  return [
    '/**',
    ' * @file Automatically generated by @pine-ui/token-compiler.',
    ' * DO NOT EDIT MANUALLY.',
    ' */',
    "export * from './vars.stylex.js';",
    '',
  ].join('\n');
}
